// Generated virtual metadata, queried on the cold registration path.
public func nativeVirtualHash(_ name: String, _ method: String) -> UInt32? {
    var current = name
    while !current.isEmpty {
        if let hash = VirtualMetadata.methods[current]?[method] { return hash }
        current = VirtualMetadata.parents[current] ?? ""
    }
    return nil
